SELECT * , (select name from admin where idx = a.reg_member) as reg_member_ FROM report a WHERE 1=1 and del_yn = 'N'
and (title like CONCAT('%', #{keyword}, '%') or content like CONCAT('%', #{keyword}, '%'))
and title like CONCAT('%', #{keyword}, '%')
and content like CONCAT('%', #{keyword}, '%')
and type = #{type}
and sYear = #{sYear}
and show_yn = #{show_yn}
order by sYear DESC, idx ASC
order by top_yn desc, reg_date desc
LIMIT #{pagination.limitStart}, #{recordSize}

SELECT count(*) FROM report WHERE 1=1 and del_yn = 'N'
and (title like CONCAT('%', #{keyword}, '%') or content like CONCAT('%', #{keyword}, '%'))
and title like CONCAT('%', #{keyword}, '%')
and content like CONCAT('%', #{keyword}, '%')
and type = #{type}
and sYear = '2022'
and sYear = #{sYear}
and show_yn = #{show_yn}

SELECT * , (select name from admin where idx = a.reg_member) as reg_member_ FROM report a WHERE 1=1
and idx = #{idx}
and acpt_no = #{acpt_no}
and del_yn = 'N'

SELECT a.*, b.id AS reg_AdminID, b.name AS reg_AdminName FROM report a, admin b WHERE a.reg_member = b.idx
AND a.idx = #{idx}
and a.acpt_no = #{acpt_no}

